def shape(g,bg):
    return {(r,c):x for r,row in enumerate(g) for c,x in enumerate(row) if x!=bg}

def f(g):
    bg=g[0][0]
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    cells={}
    for r,row in enumerate(g):
        for c,x in enumerate(row):
            if x!=bg: cells.setdefault(x,[]).append((r,c))
    for col,ps in cells.items():
        if len(ps)<2: continue
        ps=sorted(ps)
        if all(r-c==ps[0][0]-ps[0][1] for r,c in ps):  # main diag
            top=ps[0]; bot=ps[-1]
            if bot[0]+1<h and bot[1]+1<w and g[bot[0]+1][bot[1]+1]!=bg and g[bot[0]+1][bot[1]+1]!=col:
                dr=(-1,-1); start=top
            else:
                dr=(1,1); start=bot
            r,c=start[0]+dr[0],start[1]+dr[1]
            while 0<=r<h and 0<=c<w: out[r][c]=col; r+=dr[0]; c+=dr[1]
        elif all(r+c==ps[0][0]+ps[0][1] for r,c in ps):  # anti diag
            top=ps[0]; bot=ps[-1]
            if top[1]+1<w and top[0]-1>=0 and g[top[0]-1][top[1]+1]!=bg and g[top[0]-1][top[1]+1]!=col:
                dr=(1,-1); start=bot
            else:
                dr=(-1,1); start=top
            r,c=start[0]+dr[0],start[1]+dr[1]
            while 0<=r<h and 0<=c<w: out[r][c]=col; r+=dr[0]; c+=dr[1]
        elif all(c==ps[0][1] for r,c in ps):  # vertical
            top=ps[0]
            r,c=top[0]-1,top[1]+1
            while 0<=r<h and 0<=c<w: out[r][c]=col; r-=1; c+=1
    return out

